#!/usr/bin/env python3
"""Build human-readable views of reviewed contracts; never writes native CAD."""
from pathlib import Path
import json,hashlib,collections
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads((ROOT/p).read_text())
def digest(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def pins(c):return {str(p['number']):p['net'] for p in c['pins']} if isinstance(c['pins'],list) else c['pins']
def facts(c):
 path=c.get('pin_fact_file') or c.get('physical_facts')
 if path:
  p=(ROOT/'docs/design'/path).resolve() if path.startswith('../') else ROOT/path
  if p.exists():return {str(x['number']):x for x in json.loads(p.read_text())['pins']}
 mpn=c.get('mpn',c.get('exact_mpn'))
 return powerfacts.get(mpn,{})
powerfacts={d['mpn']:{str(p['number']):p for p in d['pins']} for d in read('docs/components/power_facts.json')}
contracts={n:read(f'docs/design/{n}_contract.json') for n in ('power','mcu','display','peripherals')}
allcomponents=[(n,c) for n,d in contracts.items() for c in d['components']+d.get('two_terminal_support',[])]
netends=collections.defaultdict(list)
for n,c in allcomponents:
 for p,net in pins(c).items():
  if net is not None:netends[net].append(c['ref']+'.'+p)
lines=['# Project pinouts','','2026-11-09. Generated by `tools/write_project_docs.py` from the four reviewed block contracts. Edit the owning contract and repeat the independent review before changing CAD; do not edit this generated view. Manufacturer facts remain separate in `components/`.', '', 'This index consolidates the block contracts created and reviewed before capture. Electrical assignments are reviewable; connector mating and unassigned footprints remain explicit PCB gates.', '', '## Source contracts and circuit decisions','', '| Block | Assignment source | Circuit decisions | Independent source review |','|---|---|---|---|']
for n in contracts:lines.append(f'| {n.title()} | [{n}_contract.json](design/{n}_contract.json) | [{n}.md](design/{n}.md) | [review](design/review_{n}.md) |')
lines += ['', '## Power domains and interfaces','','- USB_VBUS and DOCK_5V: separate 5 V sources into the priority mux; presence signals are active-low 3.3 V open-drain outputs. USB D+/D− remain USB differential signals.', '- VEXT_5V: selected external input. VSYS: charger power-path output. VBAT_PROTECTED: protected ordinary 1S 4.2 V LiPo pack. Battery connector polarity and exact pack/connector must be qualified before connection.', '- +3V3: shared nominal 3.3 V supply for logic and the eight RGB LEDs, including storage deep sleep. The user-approved prototype can operate below the LED specified minimum because of tolerance/transients; see the explicit bench qualification gate in implementation_status.md. +3V3_EPD: switched display and isolation-buffer supply. ACC_3V3: current-limited external accessory/IR receiver supply.', '- EPD generated analog rails are panel-controller outputs; pin18 VDD is its local 1.8 V output, never the 3.3 V input. See display decisions for bipolar bias rails.', '- All MCU GPIO/bus signals are in the 3.3 V domain. RGB_DATA drives the shared-supply LEDs directly; voltage-level analysis does not waive the LED minimum supply boundary. Internal I2C addresses: BH1730FVC 0x29, LIS2DW12 0x19, NTAG 0x55, TCA9534 0x20. External I2C is a separate bus.', '', '## Population and orientation gates','','- J102 is a two-wire battery interface: project pin1 positive, pin2 GND. That is a logical assignment, not approval of any vendor cable polarity.', '- J104 is an optional, initially unpopulated, separate cell-contact thermistor connection. R120 keeps charger CE high in this initial variant. **Onboard charging is disabled.** A sensor plus a qualified hardware temperature window and charge-current validation are required before enabling it.', '- J301 uses the panel flex contact numbering. Its connector footprint is deliberately blank pending exact panel flex, contact-side, fold and mating-view validation.', '- J501 follows Qwiic electrical ordering. J502 SAO is a project-assigned host view; exact keyed mating/mirror orientation remains a physical gate. USB shell S1–S4 aliases the one schematic SH node; power-contact shared lands are documented in the power facts.', '- DNP is recorded in contract population/value/custom fields where the installed MCP cannot set the native KiCad DNP flag. This is not a manufacturing BOM. Do not infer assembly population from the native flag alone.', '- Unused pins below are explicit NCs unless the net says otherwise. Reserved MCU GPIO35–37 are unavailable on N16R8; boot straps, reset pulls, wake and unpowered behavior are in the linked decisions.', '', '## Physical-pin assignments','']
for block in contracts:
 lines += [f'### {block.title()}', '']
 for _,c in [a for a in allcomponents if a[0]==block]:
  value=c.get('mpn') or c.get('exact_mpn') or c.get('value') or c.get('kind','support component')
  ident=c.get('bom_id', ', '.join(c.get('bom_ids',[])))
  lines += [f"#### {c['ref']}: {value}" + (f' ({ident})' if ident else ''),'']
  fs=facts(c)
  if c.get('notes'):lines += [str(c['notes']),'']
  lines += ['| Physical pin | Manufacturer function | Project net | Connected endpoints |','|---|---|---|---|']
  for p,net in pins(c).items():
   f=fs.get(str(p),{});name=f.get('name','passive terminal' if c['ref'].startswith(('R','C','L')) else 'See component facts')
   if isinstance(c['pins'],list):name=next(q.get('name',name) for q in c['pins'] if str(q['number'])==str(p))
   ends='; '.join(netends[net]) if net is not None else 'Intentional NC'
   if net in ('GND','+3V3'):ends=f'{len(netends[net])} endpoints; see net index'
   lines.append(f"| {p} | {name} | {net if net is not None else 'NC'} | {ends} |")
  lines.append('')
lines += ['## Common power-net endpoints','']
for net in ('GND','+3V3'):
 lines += [f'### {net}','','; '.join(netends[net]),'']
lines += ['## Contract snapshot','','These hashes identify the reviewed input snapshot used to generate this view. Original submission status text inside older contracts is historical; the independent review documents record acceptance and remaining gates.','']
for n in contracts:lines.append(f'- {n}: `{digest(f"docs/design/{n}_contract.json")}`')
(ROOT/'docs/pinouts.md').write_text('\n'.join(lines)+'\n')
print('Wrote docs/pinouts.md:',len(allcomponents),'components',sum(len(pins(c)) for _,c in allcomponents),'pins')

# Physical acceptance of the three display devices: source diagrams were visually
# inspected before capture; these coordinates come from disposable MCP readback.
def unbox(p):
 r=read(p)
 return json.loads(next(x['text'] for x in r['content'] if x['type']=='text'))
lines=['# Display library acceptance','','2026-11-09. Accepted schematic symbol/pad correspondence for the exact parts below. Source diagrams, symbol readback, disposable native schematic and footprint placement, and fresh renders were inspected. Main-board physical layout and manufacturing acceptance remain open.', '', 'The three disposable footprints were placed through Konnect MCP on `.build/symbolcheck/check.kicad_pcb`, queried using `get_component_pads`, and exported as SVG. The inspected derived view is `.build/symbolcheck/display_footprints_crop.svg.png`. Pin1 markers, cathode marking and non-mirrored top views agree with the original manufacturer diagrams. No main-board placement was performed.','']
for ref,mpn,fp,xy,source in [('Q901','SI1308EDL-T1-GE3','Package_TO_SOT_SMD:SOT-323_SC-70',(50,50),'Vishay 63399 Rev C p1 top view; package outline in same PDF'),('D901','MBR0530T1G','Diode_SMD:D_SOD-123',(60,50),'onsemi MBR0530T1/D Rev9 p4 CASE425 STYLE1'),('U901','SN74LVC541APWR','Package_SO:TSSOP-20_4.4x6.5mm_P0.65mm',(75,50),'TI SCAS298O p4 PW top-view pin drawing and PW0020A outline')]:
 fs=read('docs/components/'+mpn+'.pins.json');facts2={str(p['number']):p for p in fs['pins']};actual=unbox('.build/display_footprint_'+ref+'_get_component_pads.json')['pads'];assert set(facts2)=={p['number'] for p in actual}
 lines += ['## '+mpn,'',f'Footprint: `{fp}`. Source: {source}.','', '| Source pin | Function | Symbol pin | Footprint pad | Local X,Y mm |','|---|---|---|---|---|']
 for p in actual:lines.append(f"| {p['number']} | {facts2[p['number']]['name']} | {p['number']} | {p['number']} | {p['x']-xy[0]:.4f}, {p['y']-xy[1]:.4f} |")
 lines += ['','All electrical leads are represented exactly once; no exposed pad or mounting holes.','']
lines += ['## Unresolved physical work','','J301 remains an explicitly numbered panel interface, with no assigned connector footprint. AYF532435 is a candidate only; panel purchase SKU/revision, contact side, flex route, fold and pin1-to-pad1 mating remain blocked pending actual mechanical evidence. L301 requires an exact 68 µH inductor with qualified saturation/DCR and footprint. Generic passive package associations require exact MPN/DC-bias/voltage/thermal qualification.','', 'The library check establishes numbering and package correspondence. It does not establish assembled switching performance, bias overshoot, display-current budget or antenna/mechanical compatibility.']
(ROOT/'docs/components/display_library_acceptance.md').write_text('\n'.join(lines)+'\n')
for mpn in ('ED037TC1','SI1308EDL-T1-GE3','MBR0530T1G','SN74LVC541APWR'):
 p=ROOT/'docs/components'/f'{mpn}.md'
 s=p.read_text().replace('Status: source extraction complete; independent review of assignments is pending.','Status: source facts and electrical assignments independently reviewed; see [display review](../design/review_display.md). Physical and prototype gates are listed in [library acceptance](display_library_acceptance.md).')
 p.write_text(s)
print('Wrote display library acceptance and synchronized source-record status.')
